/* ============================================================
   SnapFrame — Corporate About Page
   Brand: #000 (black), #7638FA (purple), #FF7A00 (orange)
   Font: Plus Jakarta Sans
   ============================================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --purple: #7638FA;
  --purple-light: #9B6BFF;
  --purple-dark: #5A22E0;
  --purple-bg: #F3EEFF;
  --orange: #FF7A00;
  --orange-light: #FF9B38;
  --orange-bg: #FFF4E8;
  --green: #00B87A;
  --green-bg: #E6F9F2;
  --blue: #0094FF;
  --blue-bg: #E6F4FF;
  --teal: #00C4CC;
  --teal-bg: #E6FAFB;
  --black: #0A0A0A;
  --gray-900: #111827;
  --gray-700: #374151;
  --gray-500: #6B7280;
  --gray-300: #D1D5DB;
  --gray-100: #F3F4F6;
  --gray-50: #F9FAFB;
  --white: #FFFFFF;
  --gradient: linear-gradient(135deg, #7638FA 0%, #FF7A00 100%);
  --gradient-soft: linear-gradient(135deg, rgba(118,56,250,0.1) 0%, rgba(255,122,0,0.1) 100%);
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 32px;
  --radius-full: 9999px;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.06);
  --shadow-md: 0 8px 32px rgba(0,0,0,0.10);
  --shadow-lg: 0 20px 60px rgba(0,0,0,0.14);
  --transition: 0.22s cubic-bezier(0.4,0,0.2,1);
  --header-h: 72px;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

ul { list-style: none; }

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* --- Container --- */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* --- Sections --- */
.section { padding: 96px 0; }

/* --- Typography Utilities --- */
.gradient-text {
  background: var(--gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.section-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--purple);
  background: var(--purple-bg);
  padding: 5px 12px;
  border-radius: var(--radius-full);
  margin-bottom: 16px;
}
.section-label--green { color: var(--green); background: var(--green-bg); }
.section-label--orange { color: var(--orange); background: var(--orange-bg); }

.section-headline {
  font-size: clamp(1.8rem, 3.5vw, 2.8rem);
  font-weight: 800;
  line-height: 1.2;
  color: var(--black);
  margin-bottom: 20px;
}

.headline-link {
  color: var(--purple);
  transition: color var(--transition);
  white-space: nowrap;
}
.headline-link:hover { color: var(--purple-dark); }
.headline-link--green { color: var(--green); }
.headline-link--green:hover { filter: brightness(0.85); }
.headline-link--orange { color: var(--orange); }
.headline-link--orange:hover { filter: brightness(0.85); }

.section-desc {
  font-size: 1.05rem;
  color: var(--gray-700);
  max-width: 580px;
  line-height: 1.75;
  margin-bottom: 28px;
}

.cta-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--purple);
  transition: gap var(--transition), color var(--transition);
}
.cta-link:hover { gap: 10px; }
.cta-link--green { color: var(--green); }
.cta-link--green:hover { color: var(--green); }
.cta-link--orange { color: var(--orange); }
.cta-link--orange:hover { color: var(--orange); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-family: inherit;
  font-weight: 700;
  font-size: 0.95rem;
  cursor: pointer;
  transition: all var(--transition);
  border: 2px solid transparent;
  white-space: nowrap;
  text-decoration: none;
}
.btn--gradient {
  background: var(--gradient);
  color: var(--white);
  border-color: transparent;
  box-shadow: 0 4px 20px rgba(118,56,250,0.35);
}
.btn--gradient:hover {
  box-shadow: 0 8px 30px rgba(118,56,250,0.5);
  transform: translateY(-2px);
}
.btn--outline {
  background: transparent;
  color: var(--black);
  border-color: var(--gray-300);
}
.btn--outline:hover {
  border-color: var(--purple);
  color: var(--purple);
}
.btn--ghost {
  background: var(--gray-100);
  color: var(--gray-900);
  border-color: transparent;
}
.btn--ghost:hover {
  background: var(--gray-50);
  border-color: var(--gray-300);
}
.btn--lg { padding: 15px 32px; font-size: 1rem; }
.btn--full { width: 100%; }

/* ============================================================
   HEADER
   ============================================================ */
.header {
  position: fixed;
  top: 0; left: 0; right: 0;
  height: var(--header-h);
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(0,0,0,0.06);
  z-index: 1000;
  transition: box-shadow var(--transition);
}
.header.scrolled { box-shadow: var(--shadow-md); }

.header__inner {
  display: flex;
  align-items: center;
  height: 100%;
  gap: 32px;
}

.header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.15rem;
  color: var(--black);
  text-decoration: none;
  flex-shrink: 0;
}
.logo-icon {
  width: 36px; height: 36px;
  background: var(--gradient);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: white;
  font-size: 1.1rem;
}
.logo-text { letter-spacing: -0.01em; }

.header__nav { flex: 1; }
.nav-list {
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-link {
  padding: 8px 14px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--gray-700);
  transition: all var(--transition);
}
.nav-link:hover { background: var(--gray-100); color: var(--black); }

.header__actions { display: flex; align-items: center; gap: 12px; margin-left: auto; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 40px; height: 40px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}
.hamburger:hover { background: var(--gray-100); }
.hamburger__line {
  display: block;
  width: 22px; height: 2px;
  background: var(--black);
  border-radius: 2px;
  transition: all 0.3s cubic-bezier(0.4,0,0.2,1);
  transform-origin: center;
}
.hamburger.open .hamburger__line:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.hamburger.open .hamburger__line:nth-child(2) {
  opacity: 0; transform: scaleX(0);
}
.hamburger.open .hamburger__line:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ============================================================
   MOBILE NAV
   ============================================================ */
.mobile-nav {
  position: fixed;
  top: var(--header-h); right: 0; bottom: 0;
  width: min(320px, 85vw);
  background: var(--white);
  z-index: 999;
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4,0,0.2,1);
  overflow-y: auto;
  box-shadow: var(--shadow-lg);
}
.mobile-nav.open { transform: translateX(0); }

.mobile-nav__inner { padding: 24px 20px 40px; }
.mobile-nav__list { display: flex; flex-direction: column; gap: 4px; }
.mobile-nav__link {
  display: block;
  padding: 14px 16px;
  font-weight: 600;
  font-size: 1.05rem;
  color: var(--gray-900);
  border-radius: var(--radius-md);
  transition: all var(--transition);
}
.mobile-nav__link:hover { background: var(--gray-100); color: var(--purple); }
.mobile-nav__link--cta { color: var(--purple); }
.mobile-nav__divider { height: 1px; background: var(--gray-100); margin: 12px 0; }

.mobile-nav__overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.4);
  z-index: 998;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s;
}
.mobile-nav__overlay.open { opacity: 1; pointer-events: all; }

/* ============================================================
   HERO
   ============================================================ */
.hero {
  min-height: 100svh;
  padding-top: calc(var(--header-h) + 60px);
  padding-bottom: 80px;
  position: relative;
  overflow: hidden;
  background: radial-gradient(ellipse 80% 60% at 60% 20%, rgba(118,56,250,0.07) 0%, transparent 70%),
              radial-gradient(ellipse 50% 40% at 80% 70%, rgba(255,122,0,0.06) 0%, transparent 70%),
              var(--white);
}

.hero__bg-shapes { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
}
.shape--1 {
  width: 500px; height: 500px;
  background: rgba(118,56,250,0.12);
  top: -100px; right: -100px;
  animation: drift1 12s ease-in-out infinite alternate;
}
.shape--2 {
  width: 300px; height: 300px;
  background: rgba(255,122,0,0.1);
  bottom: 10%; right: 20%;
  animation: drift2 15s ease-in-out infinite alternate;
}
.shape--3 {
  width: 200px; height: 200px;
  background: rgba(118,56,250,0.08);
  bottom: 30%; left: -50px;
  animation: drift1 18s ease-in-out infinite alternate-reverse;
}
.shape--4 {
  width: 150px; height: 150px;
  background: rgba(255,122,0,0.08);
  top: 40%; left: 30%;
  animation: drift2 10s ease-in-out infinite alternate;
}
@keyframes drift1 {
  from { transform: translate(0, 0) scale(1); }
  to { transform: translate(30px, 20px) scale(1.05); }
}
@keyframes drift2 {
  from { transform: translate(0, 0) scale(1); }
  to { transform: translate(-20px, -30px) scale(0.95); }
}

.hero__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 60px;
  position: relative;
  z-index: 1;
}

.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--gradient);
  color: white;
  font-size: 0.8rem;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  margin-bottom: 24px;
}
.hero__badge i { font-size: 0.9rem; }

.hero__headline {
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--black);
  margin-bottom: 20px;
}

.hero__subtext {
  font-size: 1.1rem;
  color: var(--gray-700);
  line-height: 1.7;
  margin-bottom: 36px;
  max-width: 480px;
}

.hero__actions { display: flex; gap: 12px; flex-wrap: wrap; }

/* Phone mockup */
.hero__visual {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  padding: 40px;
}

.phone-mockup {
  width: 220px;
  background: var(--black);
  border-radius: 36px;
  padding: 12px;
  box-shadow:
    0 40px 80px rgba(0,0,0,0.25),
    0 0 0 1px rgba(255,255,255,0.08),
    inset 0 0 0 1px rgba(255,255,255,0.04);
  animation: float 5s ease-in-out infinite;
}
@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-10px); }
}

.phone-screen {
  background: #1a1a1a;
  border-radius: 26px;
  overflow: hidden;
  aspect-ratio: 9/19.5;
  display: flex;
  flex-direction: column;
}
.phone-ui { height: 100%; padding: 12px 10px; display: flex; flex-direction: column; gap: 8px; }
.phone-header { }
.phone-stories { display: flex; gap: 8px; padding: 4px 0; }
.story-bubble {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--gray-700);
  flex-shrink: 0;
}
.story-bubble.active {
  background: var(--gradient);
  box-shadow: 0 0 0 2px white, 0 0 0 3px var(--purple);
}
.phone-feed { flex: 1; display: flex; flex-direction: column; gap: 8px; overflow: hidden; }
.feed-post { border-radius: 12px; overflow: hidden; }
.feed-post__img {
  height: 90px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.8rem;
  color: rgba(255,255,255,0.6);
}
.feed-post__bar { background: #222; padding: 8px 10px; }
.feed-post__actions { display: flex; gap: 10px; color: rgba(255,255,255,0.6); font-size: 0.9rem; }

/* Float badges */
.float-badge {
  position: absolute;
  display: flex; align-items: center; gap: 8px;
  background: white;
  border-radius: var(--radius-full);
  padding: 10px 16px;
  font-size: 0.82rem;
  font-weight: 700;
  box-shadow: var(--shadow-md);
  white-space: nowrap;
  animation: float 5s ease-in-out infinite;
}
.float-badge--1 {
  top: 10%; left: 0;
  color: var(--purple);
  animation-delay: 0.5s;
}
.float-badge--1 i { color: var(--purple); font-size: 1.1rem; }
.float-badge--2 {
  bottom: 15%; right: 0;
  color: var(--orange);
  animation-delay: 1.5s;
}
.float-badge--2 i { color: var(--orange); font-size: 1.1rem; }

/* ============================================================
   FEATURES
   ============================================================ */
.features { background: var(--gray-50); }

.section-layout {
  display: flex;
  gap: 80px;
  margin-bottom: 56px;
  align-items: flex-start;
}
.section-layout .section-label { flex-shrink: 0; margin-top: 4px; }
.features__headline { font-size: clamp(1.7rem, 3vw, 2.6rem); margin-bottom: 0; }

.features-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 16px;
}

.feature-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px;
  border: 1px solid var(--gray-100);
  transition: all var(--transition);
  overflow: hidden;
  position: relative;
}
.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: transparent;
}
.feature-card--wide { grid-row: span 2; }

.feature-card__icon {
  width: 48px; height: 48px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 16px;
}
.feature-card__icon--purple { background: var(--purple-bg); color: var(--purple); }
.feature-card__icon--orange { background: var(--orange-bg); color: var(--orange); }
.feature-card__icon--blue { background: var(--blue-bg); color: var(--blue); }
.feature-card__icon--teal { background: var(--teal-bg); color: var(--teal); }

.feature-card__title {
  font-size: 1.2rem;
  font-weight: 800;
  margin-bottom: 8px;
  color: var(--black);
}
.feature-card__desc { font-size: 0.9rem; color: var(--gray-500); line-height: 1.6; }

/* Clips visual */
.feature-card__visual--clips {
  margin-top: 24px;
  background: linear-gradient(135deg, #7638FA 0%, #FF7A00 100%);
  border-radius: var(--radius-md);
  height: 140px;
  display: flex; align-items: center; justify-content: center;
  position: relative;
  overflow: hidden;
}
.clip-preview { position: relative; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; }
.clip-progress {
  position: absolute;
  bottom: 0; left: 0;
  height: 3px;
  width: 60%;
  background: rgba(255,255,255,0.8);
  border-radius: 2px;
}
.clip-play {
  font-size: 2.5rem;
  color: rgba(255,255,255,0.9);
  text-shadow: 0 2px 8px rgba(0,0,0,0.2);
}

.section-cta { margin-top: 32px; }

/* ============================================================
   SAFETY
   ============================================================ */
.safety {
  background: linear-gradient(160deg, #F0FBF7 0%, var(--white) 60%);
}
.safety__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.safety-shield {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
}
.shield-bg {
  width: 200px; height: 220px;
  background: linear-gradient(160deg, rgba(0,184,122,0.12) 0%, rgba(0,184,122,0.06) 100%);
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  position: absolute;
}
.shield-icon {
  font-size: 5rem;
  color: var(--green);
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 4px 16px rgba(0,184,122,0.3));
}
.safety-pills {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.safety-pill {
  position: absolute;
  display: flex; align-items: center; gap: 6px;
  background: white;
  border: 1px solid rgba(0,184,122,0.2);
  border-radius: var(--radius-full);
  padding: 8px 14px;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--green);
  box-shadow: var(--shadow-sm);
  white-space: nowrap;
}
.safety-pill:nth-child(1) { top: 10%; right: 5%; }
.safety-pill:nth-child(2) { top: 35%; left: 0%; }
.safety-pill:nth-child(3) { bottom: 30%; right: 0%; }
.safety-pill:nth-child(4) { bottom: 10%; left: 10%; }

/* ============================================================
   CREATORS
   ============================================================ */
.creators {
  background: linear-gradient(160deg, var(--white) 0%, #FFF9F3 100%);
}
.creators__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.creators__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-bottom: 28px;
}
.creator-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.creator-stat__num {
  font-size: 1.8rem;
  font-weight: 800;
  background: var(--gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  line-height: 1;
}
.creator-stat__label { font-size: 0.78rem; color: var(--gray-500); font-weight: 500; }

/* Creator visual */
.creators__visual { display: flex; justify-content: center; align-items: center; padding: 40px; }
.creator-cards-stack { position: relative; width: 280px; height: 280px; }

.creator-card {
  position: absolute;
  width: 220px;
  background: white;
  border-radius: var(--radius-lg);
  padding: 16px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
}
.creator-card--back { top: 0; left: 0; transform: rotate(-4deg); opacity: 0.7; }
.creator-card--front { top: 30px; right: 0; z-index: 2; transform: rotate(2deg); }
.creator-card--front:hover { transform: rotate(0deg) scale(1.02); transition: transform 0.3s; }

.creator-card__thumb {
  width: 100%; height: 100px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,0.8);
  font-size: 2rem;
  margin-bottom: 12px;
}
.creator-card__info { display: flex; flex-direction: column; gap: 2px; }
.creator-card__name { font-weight: 700; font-size: 0.9rem; }
.creator-card__followers { font-size: 0.8rem; color: var(--gray-500); }
.creator-card__badge {
  position: absolute;
  top: 10px; right: 10px;
  background: var(--orange-bg);
  color: var(--orange);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  display: flex; align-items: center; gap: 4px;
}

.earnings-badge {
  position: absolute;
  bottom: -10px; left: -10px;
  display: flex; align-items: center; gap: 10px;
  background: white;
  border-radius: var(--radius-md);
  padding: 12px 16px;
  box-shadow: var(--shadow-md);
  z-index: 3;
}
.earnings-badge > i { font-size: 1.6rem; color: var(--orange); }
.earnings-badge__num { font-weight: 800; font-size: 1.1rem; color: var(--black); line-height: 1; }
.earnings-badge__label { font-size: 0.72rem; color: var(--gray-500); margin-top: 2px; }

/* ============================================================
   TAGLINE BANNER
   ============================================================ */
.tagline-banner {
  background: var(--black);
  padding: 28px 0;
  overflow: hidden;
  position: relative;
}
.tagline-banner__inner {
  display: flex;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, black 10%, black 90%, transparent 100%);
  mask-image: linear-gradient(90deg, transparent 0%, black 10%, black 90%, transparent 100%);
}
.tagline-track {
  display: flex;
  align-items: center;
  gap: 32px;
  flex-shrink: 0;
  animation: marquee 22s linear infinite;
  white-space: nowrap;
}
.tagline-track--dup { animation-delay: -11s; }
@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-100%); }
}
.tagline-item {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--white);
  letter-spacing: -0.01em;
  flex-shrink: 0;
}
.tagline-sep { color: var(--orange); font-size: 1.1rem; flex-shrink: 0; }

/* ============================================================
   NEWS
   ============================================================ */
.news { padding: 96px 0 80px; }

.news__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 48px;
}
.news__meta .section-headline { margin-bottom: 0; }
.news__viewmore { display: flex; align-items: center; gap: 6px; font-weight: 700; color: var(--purple); padding-bottom: 4px; }
.news__viewmore:hover { gap: 10px; }
.news__viewmore-mobile { display: none; margin-top: 24px; }

.news__carousel-wrapper {
  position: relative;
  overflow: hidden;
}

.news__carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0 24px 16px;
  max-width: 1248px;
  margin: 0 auto;
  cursor: grab;
}
.news__carousel::-webkit-scrollbar { display: none; }
.news__carousel:active { cursor: grabbing; }

.news__scroll-hint {
  position: absolute;
  right: 0; top: 50%;
  transform: translateY(-50%);
  background: linear-gradient(270deg, var(--white) 60%, transparent 100%);
  width: 80px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 12px;
  pointer-events: none;
  font-size: 1.4rem;
  color: var(--gray-500);
  opacity: 0.7;
}

/* News Cards */
.news-card {
  flex: 0 0 300px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-100);
  overflow: hidden;
  scroll-snap-align: start;
  transition: all var(--transition);
  cursor: pointer;
}
.news-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: transparent;
}

.news-card__thumb {
  height: 180px;
  position: relative;
  overflow: hidden;
}
.news-card__thumb--1 { background: linear-gradient(135deg, #7638FA 0%, #A970FF 100%); }
.news-card__thumb--2 { background: linear-gradient(135deg, #FF7A00 0%, #FFD600 100%); }
.news-card__thumb--3 { background: linear-gradient(135deg, #0094FF 0%, #00C4CC 100%); }
.news-card__thumb--4 { background: linear-gradient(135deg, #00B87A 0%, #00E5A8 100%); }

.news-card__thumb-inner {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font-size: 3rem;
  color: rgba(255,255,255,0.7);
}

.news-card__body { padding: 20px; }

.news-card__tags {
  display: flex; flex-wrap: wrap; gap: 6px;
  margin-bottom: 12px;
}
.tag {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  letter-spacing: 0.03em;
}
.tag--purple { background: var(--purple-bg); color: var(--purple); }
.tag--orange { background: var(--orange-bg); color: var(--orange); }
.tag--gray { background: var(--gray-100); color: var(--gray-700); }
.tag--green { background: var(--green-bg); color: var(--green); }

.news-card__title {
  font-size: 0.95rem;
  font-weight: 700;
  line-height: 1.45;
  color: var(--black);
  margin-bottom: 12px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.news-card__date { font-size: 0.8rem; color: var(--gray-500); font-weight: 500; }

/* ============================================================
   CTA DOWNLOAD
   ============================================================ */
.cta-download {
  padding: 80px 0;
  background: var(--gray-50);
}
.cta-download__inner {
  background: var(--black);
  border-radius: var(--radius-xl);
  padding: 72px 64px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 60px;
  align-items: center;
  position: relative;
  overflow: hidden;
}
.cta-download__bg-shape {
  position: absolute;
  top: -60px; right: 200px;
  width: 400px; height: 400px;
  border-radius: 50%;
  background: var(--gradient);
  opacity: 0.15;
  filter: blur(60px);
  pointer-events: none;
}
.cta-download__content { position: relative; z-index: 1; }
.cta-download__headline {
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 800;
  color: var(--white);
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.cta-download__sub {
  font-size: clamp(1.2rem, 2.5vw, 1.8rem);
  font-weight: 400;
  color: rgba(255,255,255,0.55);
  margin-bottom: 36px;
  line-height: 1.4;
}
.cta-download__buttons { display: flex; gap: 12px; flex-wrap: wrap; }

.store-btn {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.15);
  color: white;
  border-radius: var(--radius-md);
  padding: 14px 22px;
  transition: all var(--transition);
  backdrop-filter: blur(4px);
}
.store-btn:hover {
  background: rgba(255,255,255,0.18);
  border-color: rgba(255,255,255,0.3);
  transform: translateY(-2px);
}
.store-btn__icon { font-size: 1.8rem; }
.store-btn__text { display: flex; flex-direction: column; line-height: 1.2; }
.store-btn__label { font-size: 0.7rem; opacity: 0.7; }
.store-btn__store { font-size: 1rem; font-weight: 700; }

/* Download phone visual */
.cta-download__visual { position: relative; z-index: 1; }
.download-phone {
  width: 120px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 24px;
  padding: 8px;
  box-shadow: 0 20px 40px rgba(0,0,0,0.3);
}
.download-phone__screen {
  background: rgba(255,255,255,0.05);
  border-radius: 18px;
  aspect-ratio: 9/19.5;
  display: flex;
  align-items: center;
  justify-content: center;
}
.download-phone__app {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  color: white;
}
.download-phone__logo { font-size: 2rem; }
.download-phone__name { font-size: 0.7rem; font-weight: 700; opacity: 0.8; }

/* ============================================================
   FOOTER
   ============================================================ */
.footer {
  background: var(--white);
  border-top: 1px solid var(--gray-100);
  padding: 64px 0 40px;
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 56px;
}

.footer__col-title {
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--black);
  margin-bottom: 16px;
}

.footer__links { display: flex; flex-direction: column; gap: 8px; }
.footer__links a {
  font-size: 0.88rem;
  color: var(--gray-500);
  transition: color var(--transition);
  display: inline-flex; align-items: center; gap: 4px;
}
.footer__links a:hover { color: var(--black); }
.footer__links a i { font-size: 0.75rem; opacity: 0.7; }
.footer__links--mt { margin-top: 20px; }

.footer__bottom {
  border-top: 1px solid var(--gray-100);
  padding-top: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.footer__bottom-left { display: flex; align-items: center; gap: 16px; }

.footer__logo {
  display: flex; align-items: center; gap: 8px;
  font-weight: 800; font-size: 0.95rem; color: var(--black);
}
.footer__logo i { color: var(--purple); font-size: 1.1rem; }

.footer__lang {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--gray-100);
  border: none;
  border-radius: var(--radius-full);
  padding: 6px 14px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--gray-700);
  cursor: pointer;
  transition: background var(--transition);
}
.footer__lang:hover { background: var(--gray-300); }

.footer__social { display: flex; align-items: center; gap: 8px; }
.social-icon {
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-full);
  background: var(--gray-100);
  color: var(--gray-700);
  font-size: 1rem;
  transition: all var(--transition);
}
.social-icon:hover { background: var(--black); color: var(--white); }

.footer__legal {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.footer__legal a {
  font-size: 0.8rem;
  color: var(--gray-500);
  transition: color var(--transition);
}
.footer__legal a:hover { color: var(--black); }
.footer__sep { color: var(--gray-300); font-size: 0.8rem; }

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .features-grid { grid-template-columns: 1fr 1fr; }
  .feature-card--wide { grid-row: span 1; }
}

@media (max-width: 768px) {
  :root { --header-h: 64px; }

  .header__nav { display: none; }
  .hamburger { display: flex; }

  .hero__inner { grid-template-columns: 1fr; gap: 40px; text-align: center; }
  .hero__subtext { margin-left: auto; margin-right: auto; }
  .hero__actions { justify-content: center; }
  .hero__badge { margin-left: auto; margin-right: auto; }
  .hero__visual { padding: 20px; }
  .float-badge--1 { top: 0; left: -10px; }
  .float-badge--2 { bottom: 5%; right: -10px; }

  .section { padding: 64px 0; }

  .section-layout { flex-direction: column; gap: 8px; }
  .features-grid { grid-template-columns: 1fr; }
  .feature-card--wide { grid-row: span 1; }
  .feature-card__visual--clips { height: 100px; }

  .safety__inner { grid-template-columns: 1fr; gap: 40px; }
  .safety__visual { order: -1; }
  .safety-shield { transform: scale(0.85); }

  .creators__inner { grid-template-columns: 1fr; gap: 40px; }
  .creators__visual { order: -1; }
  .creators__stats { grid-template-columns: repeat(3, 1fr); }

  .news__header { flex-direction: column; align-items: flex-start; gap: 8px; }
  .news__viewmore { display: none; }
  .news__viewmore-mobile { display: block; }
  .news-card { flex: 0 0 260px; }

  .cta-download__inner {
    grid-template-columns: 1fr;
    padding: 48px 32px;
    gap: 32px;
  }
  .cta-download__visual { display: none; }

  .footer__grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .footer__bottom { flex-direction: column; align-items: flex-start; gap: 16px; }
  .footer__social { flex-wrap: wrap; }
  .footer__legal { flex-wrap: wrap; }
}

@media (max-width: 480px) {
  .hero__headline { font-size: 2rem; }
  .hero__actions { flex-direction: column; width: 100%; }
  .hero__actions .btn { width: 100%; justify-content: center; }
  .phone-mockup { width: 180px; }
  .float-badge { font-size: 0.72rem; padding: 7px 12px; }

  .cta-download__buttons { flex-direction: column; }
  .store-btn { justify-content: center; }

  .footer__grid { grid-template-columns: 1fr 1fr; }
  .footer__bottom-left { flex-wrap: wrap; }
}

/* Touch device carousel enhancement */
@media (hover: none) {
  .news__scroll-hint { display: none; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .phone-mockup, .float-badge { animation: none; }
  .tagline-track { animation: none; }
  .shape { animation: none; }
  * { transition-duration: 0.01ms !important; }
}

/* ============================================================
   SnapFrame — Corporate About Page
   Brand: #000 (black), #7638FA (purple), #FF7A00 (orange)
   Font: Plus Jakarta Sans
   ============================================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --purple: #7638FA;
  --purple-light: #9B6BFF;
  --purple-dark: #5A22E0;
  --purple-bg: #F3EEFF;
  --orange: #FF7A00;
  --orange-light: #FF9B38;
  --orange-bg: #FFF4E8;
  --green: #00B87A;
  --green-bg: #E6F9F2;
  --blue: #0094FF;
  --blue-bg: #E6F4FF;
  --teal: #00C4CC;
  --teal-bg: #E6FAFB;
  --black: #0A0A0A;
  --gray-900: #111827;
  --gray-700: #374151;
  --gray-500: #6B7280;
  --gray-300: #D1D5DB;
  --gray-100: #F3F4F6;
  --gray-50: #F9FAFB;
  --white: #FFFFFF;
  --gradient: linear-gradient(135deg, #7638FA 0%, #FF7A00 100%);
  --gradient-soft: linear-gradient(135deg, rgba(118,56,250,0.1) 0%, rgba(255,122,0,0.1) 100%);
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 32px;
  --radius-full: 9999px;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.06);
  --shadow-md: 0 8px 32px rgba(0,0,0,0.10);
  --shadow-lg: 0 20px 60px rgba(0,0,0,0.14);
  --transition: 0.22s cubic-bezier(0.4,0,0.2,1);
  --header-h: 72px;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

ul { list-style: none; }

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* --- Container --- */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* --- Sections --- */
.section { padding: 96px 0; }

/* --- Typography Utilities --- */
.gradient-text {
  background: var(--gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.section-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--purple);
  background: var(--purple-bg);
  padding: 5px 12px;
  border-radius: var(--radius-full);
  margin-bottom: 16px;
}
.section-label--green { color: var(--green); background: var(--green-bg); }
.section-label--orange { color: var(--orange); background: var(--orange-bg); }

.section-headline {
  font-size: clamp(1.8rem, 3.5vw, 2.8rem);
  font-weight: 800;
  line-height: 1.2;
  color: var(--black);
  margin-bottom: 20px;
}

.headline-link {
  color: var(--purple);
  transition: color var(--transition);
  white-space: nowrap;
}
.headline-link:hover { color: var(--purple-dark); }
.headline-link--green { color: var(--green); }
.headline-link--green:hover { filter: brightness(0.85); }
.headline-link--orange { color: var(--orange); }
.headline-link--orange:hover { filter: brightness(0.85); }

.section-desc {
  font-size: 1.05rem;
  color: var(--gray-700);
  max-width: 580px;
  line-height: 1.75;
  margin-bottom: 28px;
}

.cta-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--purple);
  transition: gap var(--transition), color var(--transition);
}
.cta-link:hover { gap: 10px; }
.cta-link--green { color: var(--green); }
.cta-link--green:hover { color: var(--green); }
.cta-link--orange { color: var(--orange); }
.cta-link--orange:hover { color: var(--orange); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-family: inherit;
  font-weight: 700;
  font-size: 0.95rem;
  cursor: pointer;
  transition: all var(--transition);
  border: 2px solid transparent;
  white-space: nowrap;
  text-decoration: none;
}
.btn--gradient {
  background: var(--gradient);
  color: var(--white);
  border-color: transparent;
  box-shadow: 0 4px 20px rgba(118,56,250,0.35);
}
.btn--gradient:hover {
  box-shadow: 0 8px 30px rgba(118,56,250,0.5);
  transform: translateY(-2px);
}
.btn--outline {
  background: transparent;
  color: var(--black);
  border-color: var(--gray-300);
}
.btn--outline:hover {
  border-color: var(--purple);
  color: var(--purple);
}
.btn--ghost {
  background: var(--gray-100);
  color: var(--gray-900);
  border-color: transparent;
}
.btn--ghost:hover {
  background: var(--gray-50);
  border-color: var(--gray-300);
}
.btn--lg { padding: 15px 32px; font-size: 1rem; }
.btn--full { width: 100%; }

/* ============================================================
   HEADER
   ============================================================ */
.header {
  position: fixed;
  top: 0; left: 0; right: 0;
  height: var(--header-h);
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(0,0,0,0.06);
  z-index: 1000;
  transition: box-shadow var(--transition);
}
.header.scrolled { box-shadow: var(--shadow-md); }

.header__inner {
  display: flex;
  align-items: center;
  height: 100%;
  gap: 32px;
}

.header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.15rem;
  color: var(--black);
  text-decoration: none;
  flex-shrink: 0;
}
.logo-icon {
  width: 36px; height: 36px;
  background: var(--gradient);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: white;
  font-size: 1.1rem;
}
.logo-text { letter-spacing: -0.01em; }

.header__nav { flex: 1; }
.nav-list {
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-link {
  padding: 8px 14px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--gray-700);
  transition: all var(--transition);
}
.nav-link:hover { background: var(--gray-100); color: var(--black); }

.header__actions { display: flex; align-items: center; gap: 12px; margin-left: auto; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 40px; height: 40px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}
.hamburger:hover { background: var(--gray-100); }
.hamburger__line {
  display: block;
  width: 22px; height: 2px;
  background: var(--black);
  border-radius: 2px;
  transition: all 0.3s cubic-bezier(0.4,0,0.2,1);
  transform-origin: center;
}
.hamburger.open .hamburger__line:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.hamburger.open .hamburger__line:nth-child(2) {
  opacity: 0; transform: scaleX(0);
}
.hamburger.open .hamburger__line:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ============================================================
   MOBILE NAV
   ============================================================ */
.mobile-nav {
  position: fixed;
  top: var(--header-h); right: 0; bottom: 0;
  width: min(320px, 85vw);
  background: var(--white);
  z-index: 999;
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4,0,0.2,1);
  overflow-y: auto;
  box-shadow: var(--shadow-lg);
}
.mobile-nav.open { transform: translateX(0); }

.mobile-nav__inner { padding: 24px 20px 40px; }
.mobile-nav__list { display: flex; flex-direction: column; gap: 4px; }
.mobile-nav__link {
  display: block;
  padding: 14px 16px;
  font-weight: 600;
  font-size: 1.05rem;
  color: var(--gray-900);
  border-radius: var(--radius-md);
  transition: all var(--transition);
}
.mobile-nav__link:hover { background: var(--gray-100); color: var(--purple); }
.mobile-nav__link--cta { color: var(--purple); }
.mobile-nav__divider { height: 1px; background: var(--gray-100); margin: 12px 0; }

.mobile-nav__overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.4);
  z-index: 998;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s;
}
.mobile-nav__overlay.open { opacity: 1; pointer-events: all; }

/* ============================================================
   HERO
   ============================================================ */
.hero {
  min-height: 100svh;
  padding-top: calc(var(--header-h) + 60px);
  padding-bottom: 80px;
  position: relative;
  overflow: hidden;
  background: radial-gradient(ellipse 80% 60% at 60% 20%, rgba(118,56,250,0.07) 0%, transparent 70%),
              radial-gradient(ellipse 50% 40% at 80% 70%, rgba(255,122,0,0.06) 0%, transparent 70%),
              var(--white);
}

.hero__bg-shapes { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
}
.shape--1 {
  width: 500px; height: 500px;
  background: rgba(118,56,250,0.12);
  top: -100px; right: -100px;
  animation: drift1 12s ease-in-out infinite alternate;
}
.shape--2 {
  width: 300px; height: 300px;
  background: rgba(255,122,0,0.1);
  bottom: 10%; right: 20%;
  animation: drift2 15s ease-in-out infinite alternate;
}
.shape--3 {
  width: 200px; height: 200px;
  background: rgba(118,56,250,0.08);
  bottom: 30%; left: -50px;
  animation: drift1 18s ease-in-out infinite alternate-reverse;
}
.shape--4 {
  width: 150px; height: 150px;
  background: rgba(255,122,0,0.08);
  top: 40%; left: 30%;
  animation: drift2 10s ease-in-out infinite alternate;
}
@keyframes drift1 {
  from { transform: translate(0, 0) scale(1); }
  to { transform: translate(30px, 20px) scale(1.05); }
}
@keyframes drift2 {
  from { transform: translate(0, 0) scale(1); }
  to { transform: translate(-20px, -30px) scale(0.95); }
}

.hero__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 60px;
  position: relative;
  z-index: 1;
}

.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--gradient);
  color: white;
  font-size: 0.8rem;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  margin-bottom: 24px;
}
.hero__badge i { font-size: 0.9rem; }

.hero__headline {
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--black);
  margin-bottom: 20px;
}

.hero__subtext {
  font-size: 1.1rem;
  color: var(--gray-700);
  line-height: 1.7;
  margin-bottom: 36px;
  max-width: 480px;
}

.hero__actions { display: flex; gap: 12px; flex-wrap: wrap; }

/* Phone mockup */
.hero__visual {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  padding: 40px;
}

.phone-mockup {
  width: 220px;
  background: var(--black);
  border-radius: 36px;
  padding: 12px;
  box-shadow:
    0 40px 80px rgba(0,0,0,0.25),
    0 0 0 1px rgba(255,255,255,0.08),
    inset 0 0 0 1px rgba(255,255,255,0.04);
  animation: float 5s ease-in-out infinite;
}
@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-10px); }
}

.phone-screen {
  background: #1a1a1a;
  border-radius: 26px;
  overflow: hidden;
  aspect-ratio: 9/19.5;
  display: flex;
  flex-direction: column;
}
.phone-ui { height: 100%; padding: 12px 10px; display: flex; flex-direction: column; gap: 8px; }
.phone-header { }
.phone-stories { display: flex; gap: 8px; padding: 4px 0; }
.story-bubble {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--gray-700);
  flex-shrink: 0;
}
.story-bubble.active {
  background: var(--gradient);
  box-shadow: 0 0 0 2px white, 0 0 0 3px var(--purple);
}
.phone-feed { flex: 1; display: flex; flex-direction: column; gap: 8px; overflow: hidden; }
.feed-post { border-radius: 12px; overflow: hidden; }
.feed-post__img {
  height: 90px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.8rem;
  color: rgba(255,255,255,0.6);
}
.feed-post__bar { background: #222; padding: 8px 10px; }
.feed-post__actions { display: flex; gap: 10px; color: rgba(255,255,255,0.6); font-size: 0.9rem; }

/* Float badges */
.float-badge {
  position: absolute;
  display: flex; align-items: center; gap: 8px;
  background: white;
  border-radius: var(--radius-full);
  padding: 10px 16px;
  font-size: 0.82rem;
  font-weight: 700;
  box-shadow: var(--shadow-md);
  white-space: nowrap;
  animation: float 5s ease-in-out infinite;
}
.float-badge--1 {
  top: 10%; left: 0;
  color: var(--purple);
  animation-delay: 0.5s;
}
.float-badge--1 i { color: var(--purple); font-size: 1.1rem; }
.float-badge--2 {
  bottom: 15%; right: 0;
  color: var(--orange);
  animation-delay: 1.5s;
}
.float-badge--2 i { color: var(--orange); font-size: 1.1rem; }

/* ============================================================
   FEATURES
   ============================================================ */
.features { background: var(--gray-50); }

.section-layout {
  display: flex;
  gap: 80px;
  margin-bottom: 56px;
  align-items: flex-start;
}
.section-layout .section-label { flex-shrink: 0; margin-top: 4px; }
.features__headline { font-size: clamp(1.7rem, 3vw, 2.6rem); margin-bottom: 0; }

.features-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 16px;
}

.feature-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px;
  border: 1px solid var(--gray-100);
  transition: all var(--transition);
  overflow: hidden;
  position: relative;
}
.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: transparent;
}
.feature-card--wide { grid-row: span 2; }

.feature-card__icon {
  width: 48px; height: 48px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 16px;
}
.feature-card__icon--purple { background: var(--purple-bg); color: var(--purple); }
.feature-card__icon--orange { background: var(--orange-bg); color: var(--orange); }
.feature-card__icon--blue { background: var(--blue-bg); color: var(--blue); }
.feature-card__icon--teal { background: var(--teal-bg); color: var(--teal); }

.feature-card__title {
  font-size: 1.2rem;
  font-weight: 800;
  margin-bottom: 8px;
  color: var(--black);
}
.feature-card__desc { font-size: 0.9rem; color: var(--gray-500); line-height: 1.6; }

/* Clips visual */
.feature-card__visual--clips {
  margin-top: 24px;
  background: linear-gradient(135deg, #7638FA 0%, #FF7A00 100%);
  border-radius: var(--radius-md);
  height: 140px;
  display: flex; align-items: center; justify-content: center;
  position: relative;
  overflow: hidden;
}
.clip-preview { position: relative; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; }
.clip-progress {
  position: absolute;
  bottom: 0; left: 0;
  height: 3px;
  width: 60%;
  background: rgba(255,255,255,0.8);
  border-radius: 2px;
}
.clip-play {
  font-size: 2.5rem;
  color: rgba(255,255,255,0.9);
  text-shadow: 0 2px 8px rgba(0,0,0,0.2);
}

.section-cta { margin-top: 32px; }

/* ============================================================
   SAFETY
   ============================================================ */
.safety {
  background: linear-gradient(160deg, #F0FBF7 0%, var(--white) 60%);
}
.safety__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.safety-shield {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
}
.shield-bg {
  width: 200px; height: 220px;
  background: linear-gradient(160deg, rgba(0,184,122,0.12) 0%, rgba(0,184,122,0.06) 100%);
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  position: absolute;
}
.shield-icon {
  font-size: 5rem;
  color: var(--green);
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 4px 16px rgba(0,184,122,0.3));
}
.safety-pills {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.safety-pill {
  position: absolute;
  display: flex; align-items: center; gap: 6px;
  background: white;
  border: 1px solid rgba(0,184,122,0.2);
  border-radius: var(--radius-full);
  padding: 8px 14px;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--green);
  box-shadow: var(--shadow-sm);
  white-space: nowrap;
}
.safety-pill:nth-child(1) { top: 10%; right: 5%; }
.safety-pill:nth-child(2) { top: 35%; left: 0%; }
.safety-pill:nth-child(3) { bottom: 30%; right: 0%; }
.safety-pill:nth-child(4) { bottom: 10%; left: 10%; }

/* ============================================================
   CREATORS
   ============================================================ */
.creators {
  background: linear-gradient(160deg, var(--white) 0%, #FFF9F3 100%);
}
.creators__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.creators__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-bottom: 28px;
}
.creator-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.creator-stat__num {
  font-size: 1.8rem;
  font-weight: 800;
  background: var(--gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  line-height: 1;
}
.creator-stat__label { font-size: 0.78rem; color: var(--gray-500); font-weight: 500; }

/* Creator visual */
.creators__visual { display: flex; justify-content: center; align-items: center; padding: 40px; }
.creator-cards-stack { position: relative; width: 280px; height: 280px; }

.creator-card {
  position: absolute;
  width: 220px;
  background: white;
  border-radius: var(--radius-lg);
  padding: 16px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
}
.creator-card--back { top: 0; left: 0; transform: rotate(-4deg); opacity: 0.7; }
.creator-card--front { top: 30px; right: 0; z-index: 2; transform: rotate(2deg); }
.creator-card--front:hover { transform: rotate(0deg) scale(1.02); transition: transform 0.3s; }

.creator-card__thumb {
  width: 100%; height: 100px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,0.8);
  font-size: 2rem;
  margin-bottom: 12px;
}
.creator-card__info { display: flex; flex-direction: column; gap: 2px; }
.creator-card__name { font-weight: 700; font-size: 0.9rem; }
.creator-card__followers { font-size: 0.8rem; color: var(--gray-500); }
.creator-card__badge {
  position: absolute;
  top: 10px; right: 10px;
  background: var(--orange-bg);
  color: var(--orange);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  display: flex; align-items: center; gap: 4px;
}

.earnings-badge {
  position: absolute;
  bottom: -10px; left: -10px;
  display: flex; align-items: center; gap: 10px;
  background: white;
  border-radius: var(--radius-md);
  padding: 12px 16px;
  box-shadow: var(--shadow-md);
  z-index: 3;
}
.earnings-badge > i { font-size: 1.6rem; color: var(--orange); }
.earnings-badge__num { font-weight: 800; font-size: 1.1rem; color: var(--black); line-height: 1; }
.earnings-badge__label { font-size: 0.72rem; color: var(--gray-500); margin-top: 2px; }

/* ============================================================
   TAGLINE BANNER
   ============================================================ */
.tagline-banner {
  background: var(--black);
  padding: 28px 0;
  overflow: hidden;
  position: relative;
}
.tagline-banner__inner {
  display: flex;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, black 10%, black 90%, transparent 100%);
  mask-image: linear-gradient(90deg, transparent 0%, black 10%, black 90%, transparent 100%);
}
.tagline-track {
  display: flex;
  align-items: center;
  gap: 32px;
  flex-shrink: 0;
  animation: marquee 22s linear infinite;
  white-space: nowrap;
}
.tagline-track--dup { animation-delay: -11s; }
@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-100%); }
}
.tagline-item {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--white);
  letter-spacing: -0.01em;
  flex-shrink: 0;
}
.tagline-sep { color: var(--orange); font-size: 1.1rem; flex-shrink: 0; }

/* ============================================================
   NEWS
   ============================================================ */
.news { padding: 96px 0 80px; }

.news__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 48px;
}
.news__meta .section-headline { margin-bottom: 0; }
.news__viewmore { display: flex; align-items: center; gap: 6px; font-weight: 700; color: var(--purple); padding-bottom: 4px; }
.news__viewmore:hover { gap: 10px; }
.news__viewmore-mobile { display: none; margin-top: 24px; }

.news__carousel-wrapper {
  position: relative;
  overflow: hidden;
}

.news__carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0 24px 16px;
  max-width: 1248px;
  margin: 0 auto;
  cursor: grab;
}
.news__carousel::-webkit-scrollbar { display: none; }
.news__carousel:active { cursor: grabbing; }

.news__scroll-hint {
  position: absolute;
  right: 0; top: 50%;
  transform: translateY(-50%);
  background: linear-gradient(270deg, var(--white) 60%, transparent 100%);
  width: 80px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 12px;
  pointer-events: none;
  font-size: 1.4rem;
  color: var(--gray-500);
  opacity: 0.7;
}

/* News Cards */
.news-card {
  flex: 0 0 300px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-100);
  overflow: hidden;
  scroll-snap-align: start;
  transition: all var(--transition);
  cursor: pointer;
}
.news-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: transparent;
}

.news-card__thumb {
  height: 180px;
  position: relative;
  overflow: hidden;
}
.news-card__thumb--1 { background: linear-gradient(135deg, #7638FA 0%, #A970FF 100%); }
.news-card__thumb--2 { background: linear-gradient(135deg, #FF7A00 0%, #FFD600 100%); }
.news-card__thumb--3 { background: linear-gradient(135deg, #0094FF 0%, #00C4CC 100%); }
.news-card__thumb--4 { background: linear-gradient(135deg, #00B87A 0%, #00E5A8 100%); }

.news-card__thumb-inner {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font-size: 3rem;
  color: rgba(255,255,255,0.7);
}

.news-card__body { padding: 20px; }

.news-card__tags {
  display: flex; flex-wrap: wrap; gap: 6px;
  margin-bottom: 12px;
}
.tag {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  letter-spacing: 0.03em;
}
.tag--purple { background: var(--purple-bg); color: var(--purple); }
.tag--orange { background: var(--orange-bg); color: var(--orange); }
.tag--gray { background: var(--gray-100); color: var(--gray-700); }
.tag--green { background: var(--green-bg); color: var(--green); }

.news-card__title {
  font-size: 0.95rem;
  font-weight: 700;
  line-height: 1.45;
  color: var(--black);
  margin-bottom: 12px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.news-card__date { font-size: 0.8rem; color: var(--gray-500); font-weight: 500; }

/* ============================================================
   CTA DOWNLOAD
   ============================================================ */
.cta-download {
  padding: 80px 0;
  background: var(--gray-50);
}
.cta-download__inner {
  background: var(--black);
  border-radius: var(--radius-xl);
  padding: 72px 64px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 60px;
  align-items: center;
  position: relative;
  overflow: hidden;
}
.cta-download__bg-shape {
  position: absolute;
  top: -60px; right: 200px;
  width: 400px; height: 400px;
  border-radius: 50%;
  background: var(--gradient);
  opacity: 0.15;
  filter: blur(60px);
  pointer-events: none;
}
.cta-download__content { position: relative; z-index: 1; }
.cta-download__headline {
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 800;
  color: var(--white);
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.cta-download__sub {
  font-size: clamp(1.2rem, 2.5vw, 1.8rem);
  font-weight: 400;
  color: rgba(255,255,255,0.55);
  margin-bottom: 36px;
  line-height: 1.4;
}
.cta-download__buttons { display: flex; gap: 12px; flex-wrap: wrap; }

.store-btn {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.15);
  color: white;
  border-radius: var(--radius-md);
  padding: 14px 22px;
  transition: all var(--transition);
  backdrop-filter: blur(4px);
}
.store-btn:hover {
  background: rgba(255,255,255,0.18);
  border-color: rgba(255,255,255,0.3);
  transform: translateY(-2px);
}
.store-btn__icon { font-size: 1.8rem; }
.store-btn__text { display: flex; flex-direction: column; line-height: 1.2; }
.store-btn__label { font-size: 0.7rem; opacity: 0.7; }
.store-btn__store { font-size: 1rem; font-weight: 700; }

/* Download phone visual */
.cta-download__visual { position: relative; z-index: 1; }
.download-phone {
  width: 120px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 24px;
  padding: 8px;
  box-shadow: 0 20px 40px rgba(0,0,0,0.3);
}
.download-phone__screen {
  background: rgba(255,255,255,0.05);
  border-radius: 18px;
  aspect-ratio: 9/19.5;
  display: flex;
  align-items: center;
  justify-content: center;
}
.download-phone__app {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  color: white;
}
.download-phone__logo { font-size: 2rem; }
.download-phone__name { font-size: 0.7rem; font-weight: 700; opacity: 0.8; }

/* ============================================================
   FOOTER
   ============================================================ */
.footer {
  background: var(--white);
  border-top: 1px solid var(--gray-100);
  padding: 64px 0 40px;
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 56px;
}

.footer__col-title {
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--black);
  margin-bottom: 16px;
}

.footer__links { display: flex; flex-direction: column; gap: 8px; }
.footer__links a {
  font-size: 0.88rem;
  color: var(--gray-500);
  transition: color var(--transition);
  display: inline-flex; align-items: center; gap: 4px;
}
.footer__links a:hover { color: var(--black); }
.footer__links a i { font-size: 0.75rem; opacity: 0.7; }
.footer__links--mt { margin-top: 20px; }

.footer__bottom {
  border-top: 1px solid var(--gray-100);
  padding-top: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.footer__bottom-left { display: flex; align-items: center; gap: 16px; }

.footer__logo {
  display: flex; align-items: center; gap: 8px;
  font-weight: 800; font-size: 0.95rem; color: var(--black);
}
.footer__logo i { color: var(--purple); font-size: 1.1rem; }

.footer__lang {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--gray-100);
  border: none;
  border-radius: var(--radius-full);
  padding: 6px 14px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--gray-700);
  cursor: pointer;
  transition: background var(--transition);
}
.footer__lang:hover { background: var(--gray-300); }

.footer__social { display: flex; align-items: center; gap: 8px; }
.social-icon {
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-full);
  background: var(--gray-100);
  color: var(--gray-700);
  font-size: 1rem;
  transition: all var(--transition);
}
.social-icon:hover { background: var(--black); color: var(--white); }

.footer__legal {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.footer__legal a {
  font-size: 0.8rem;
  color: var(--gray-500);
  transition: color var(--transition);
}
.footer__legal a:hover { color: var(--black); }
.footer__sep { color: var(--gray-300); font-size: 0.8rem; }

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .features-grid { grid-template-columns: 1fr 1fr; }
  .feature-card--wide { grid-row: span 1; }
}

@media (max-width: 768px) {
  :root { --header-h: 64px; }

  .header__nav { display: none; }
  .hamburger { display: flex; }

  .hero__inner { grid-template-columns: 1fr; gap: 40px; text-align: center; }
  .hero__subtext { margin-left: auto; margin-right: auto; }
  .hero__actions { justify-content: center; }
  .hero__badge { margin-left: auto; margin-right: auto; }
  .hero__visual { padding: 20px; }
  .float-badge--1 { top: 0; left: -10px; }
  .float-badge--2 { bottom: 5%; right: -10px; }

  .section { padding: 64px 0; }

  .section-layout { flex-direction: column; gap: 8px; }
  .features-grid { grid-template-columns: 1fr; }
  .feature-card--wide { grid-row: span 1; }
  .feature-card__visual--clips { height: 100px; }

  .safety__inner { grid-template-columns: 1fr; gap: 40px; }
  .safety__visual { order: -1; }
  .safety-shield { transform: scale(0.85); }

  .creators__inner { grid-template-columns: 1fr; gap: 40px; }
  .creators__visual { order: -1; }
  .creators__stats { grid-template-columns: repeat(3, 1fr); }

  .news__header { flex-direction: column; align-items: flex-start; gap: 8px; }
  .news__viewmore { display: none; }
  .news__viewmore-mobile { display: block; }
  .news-card { flex: 0 0 260px; }

  .cta-download__inner {
    grid-template-columns: 1fr;
    padding: 48px 32px;
    gap: 32px;
  }
  .cta-download__visual { display: none; }

  .footer__grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .footer__bottom { flex-direction: column; align-items: flex-start; gap: 16px; }
  .footer__social { flex-wrap: wrap; }
  .footer__legal { flex-wrap: wrap; }
}

@media (max-width: 480px) {
  .hero__headline { font-size: 2rem; }
  .hero__actions { flex-direction: column; width: 100%; }
  .hero__actions .btn { width: 100%; justify-content: center; }
  .phone-mockup { width: 180px; }
  .float-badge { font-size: 0.72rem; padding: 7px 12px; }

  .cta-download__buttons { flex-direction: column; }
  .store-btn { justify-content: center; }

  .footer__grid { grid-template-columns: 1fr 1fr; }
  .footer__bottom-left { flex-wrap: wrap; }
}

/* Touch device carousel enhancement */
@media (hover: none) {
  .news__scroll-hint { display: none; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .phone-mockup, .float-badge { animation: none; }
  .tagline-track { animation: none; }
  .shape { animation: none; }
  * { transition-duration: 0.01ms !important; }
}

raw_arguments.content:
/* ============================================================
   SnapFrame — Corporate About Page
   Brand: #000 (black), #7638FA (purple), #FF7A00 (orange)
   Font: Plus Jakarta Sans
   ============================================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --purple: #7638FA;
  --purple-light: #9B6BFF;
  --purple-dark: #5A22E0;
  --purple-bg: #F3EEFF;
  --orange: #FF7A00;
  --orange-light: #FF9B38;
  --orange-bg: #FFF4E8;
  --green: #00B87A;
  --green-bg: #E6F9F2;
  --blue: #0094FF;
  --blue-bg: #E6F4FF;
  --teal: #00C4CC;
  --teal-bg: #E6FAFB;
  --black: #0A0A0A;
  --gray-900: #111827;
  --gray-700: #374151;
  --gray-500: #6B7280;
  --gray-300: #D1D5DB;
  --gray-100: #F3F4F6;
  --gray-50: #F9FAFB;
  --white: #FFFFFF;
  --gradient: linear-gradient(135deg, #7638FA 0%, #FF7A00 100%);
  --gradient-soft: linear-gradient(135deg, rgba(118,56,250,0.1) 0%, rgba(255,122,0,0.1) 100%);
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 32px;
  --radius-full: 9999px;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.06);
  --shadow-md: 0 8px 32px rgba(0,0,0,0.10);
  --shadow-lg: 0 20px 60px rgba(0,0,0,0.14);
  --transition: 0.22s cubic-bezier(0.4,0,0.2,1);
  --header-h: 72px;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

ul { list-style: none; }

.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* --- Container --- */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* --- Sections --- */
.section { padding: 96px 0; }

/* --- Typography Utilities --- */
.gradient-text {
  background: var(--gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.section-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--purple);
  background: var(--purple-bg);
  padding: 5px 12px;
  border-radius: var(--radius-full);
  margin-bottom: 16px;
}
.section-label--green { color: var(--green); background: var(--green-bg); }
.section-label--orange { color: var(--orange); background: var(--orange-bg); }

.section-headline {
  font-size: clamp(1.8rem, 3.5vw, 2.8rem);
  font-weight: 800;
  line-height: 1.2;
  color: var(--black);
  margin-bottom: 20px;
}

.headline-link {
  color: var(--purple);
  transition: color var(--transition);
  white-space: nowrap;
}
.headline-link:hover { color: var(--purple-dark); }
.headline-link--green { color: var(--green); }
.headline-link--green:hover { filter: brightness(0.85); }
.headline-link--orange { color: var(--orange); }
.headline-link--orange:hover { filter: brightness(0.85); }

.section-desc {
  font-size: 1.05rem;
  color: var(--gray-700);
  max-width: 580px;
  line-height: 1.75;
  margin-bottom: 28px;
}

.cta-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--purple);
  transition: gap var(--transition), color var(--transition);
}
.cta-link:hover { gap: 10px; }
.cta-link--green { color: var(--green); }
.cta-link--green:hover { color: var(--green); }
.cta-link--orange { color: var(--orange); }
.cta-link--orange:hover { color: var(--orange); }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-family: inherit;
  font-weight: 700;
  font-size: 0.95rem;
  cursor: pointer;
  transition: all var(--transition);
  border: 2px solid transparent;
  white-space: nowrap;
  text-decoration: none;
}
.btn--gradient {
  background: var(--gradient);
  color: var(--white);
  border-color: transparent;
  box-shadow: 0 4px 20px rgba(118,56,250,0.35);
}
.btn--gradient:hover {
  box-shadow: 0 8px 30px rgba(118,56,250,0.5);
  transform: translateY(-2px);
}
.btn--outline {
  background: transparent;
  color: var(--black);
  border-color: var(--gray-300);
}
.btn--outline:hover {
  border-color: var(--purple);
  color: var(--purple);
}
.btn--ghost {
  background: var(--gray-100);
  color: var(--gray-900);
  border-color: transparent;
}
.btn--ghost:hover {
  background: var(--gray-50);
  border-color: var(--gray-300);
}
.btn--lg { padding: 15px 32px; font-size: 1rem; }
.btn--full { width: 100%; }

/* ============================================================
   HEADER
   ============================================================ */
.header {
  position: fixed;
  top: 0; left: 0; right: 0;
  height: var(--header-h);
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(0,0,0,0.06);
  z-index: 1000;
  transition: box-shadow var(--transition);
}
.header.scrolled { box-shadow: var(--shadow-md); }

.header__inner {
  display: flex;
  align-items: center;
  height: 100%;
  gap: 32px;
}

.header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.15rem;
  color: var(--black);
  text-decoration: none;
  flex-shrink: 0;
}
.logo-icon {
  width: 36px; height: 36px;
  background: var(--gradient);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: white;
  font-size: 1.1rem;
}
.logo-text { letter-spacing: -0.01em; }

.header__nav { flex: 1; }
.nav-list {
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-link {
  padding: 8px 14px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--gray-700);
  transition: all var(--transition);
}
.nav-link:hover { background: var(--gray-100); color: var(--black); }

.header__actions { display: flex; align-items: center; gap: 12px; margin-left: auto; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 40px; height: 40px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}
.hamburger:hover { background: var(--gray-100); }
.hamburger__line {
  display: block;
  width: 22px; height: 2px;
  background: var(--black);
  border-radius: 2px;
  transition: all 0.3s cubic-bezier(0.4,0,0.2,1);
  transform-origin: center;
}
.hamburger.open .hamburger__line:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.hamburger.open .hamburger__line:nth-child(2) {
  opacity: 0; transform: scaleX(0);
}
.hamburger.open .hamburger__line:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ============================================================
   MOBILE NAV
   ============================================================ */
.mobile-nav {
  position: fixed;
  top: var(--header-h); right: 0; bottom: 0;
  width: min(320px, 85vw);
  background: var(--white);
  z-index: 999;
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4,0,0.2,1);
  overflow-y: auto;
  box-shadow: var(--shadow-lg);
}
.mobile-nav.open { transform: translateX(0); }

.mobile-nav__inner { padding: 24px 20px 40px; }
.mobile-nav__list { display: flex; flex-direction: column; gap: 4px; }
.mobile-nav__link {
  display: block;
  padding: 14px 16px;
  font-weight: 600;
  font-size: 1.05rem;
  color: var(--gray-900);
  border-radius: var(--radius-md);
  transition: all var(--transition);
}
.mobile-nav__link:hover { background: var(--gray-100); color: var(--purple); }
.mobile-nav__link--cta { color: var(--purple); }
.mobile-nav__divider { height: 1px; background: var(--gray-100); margin: 12px 0; }

.mobile-nav__overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.4);
  z-index: 998;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s;
}
.mobile-nav__overlay.open { opacity: 1; pointer-events: all; }

/* ============================================================
   HERO
   ============================================================ */
.hero {
  min-height: 100svh;
  padding-top: calc(var(--header-h) + 60px);
  padding-bottom: 80px;
  position: relative;
  overflow: hidden;
  background: radial-gradient(ellipse 80% 60% at 60% 20%, rgba(118,56,250,0.07) 0%, transparent 70%),
              radial-gradient(ellipse 50% 40% at 80% 70%, rgba(255,122,0,0.06) 0%, transparent 70%),
              var(--white);
}

.hero__bg-shapes { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
}
.shape--1 {
  width: 500px; height: 500px;
  background: rgba(118,56,250,0.12);
  top: -100px; right: -100px;
  animation: drift1 12s ease-in-out infinite alternate;
}
.shape--2 {
  width: 300px; height: 300px;
  background: rgba(255,122,0,0.1);
  bottom: 10%; right: 20%;
  animation: drift2 15s ease-in-out infinite alternate;
}
.shape--3 {
  width: 200px; height: 200px;
  background: rgba(118,56,250,0.08);
  bottom: 30%; left: -50px;
  animation: drift1 18s ease-in-out infinite alternate-reverse;
}
.shape--4 {
  width: 150px; height: 150px;
  background: rgba(255,122,0,0.08);
  top: 40%; left: 30%;
  animation: drift2 10s ease-in-out infinite alternate;
}
@keyframes drift1 {
  from { transform: translate(0, 0) scale(1); }
  to { transform: translate(30px, 20px) scale(1.05); }
}
@keyframes drift2 {
  from { transform: translate(0, 0) scale(1); }
  to { transform: translate(-20px, -30px) scale(0.95); }
}

.hero__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 60px;
  position: relative;
  z-index: 1;
}

.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--gradient);
  color: white;
  font-size: 0.8rem;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  margin-bottom: 24px;
}
.hero__badge i { font-size: 0.9rem; }

.hero__headline {
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--black);
  margin-bottom: 20px;
}

.hero__subtext {
  font-size: 1.1rem;
  color: var(--gray-700);
  line-height: 1.7;
  margin-bottom: 36px;
  max-width: 480px;
}

.hero__actions { display: flex; gap: 12px; flex-wrap: wrap; }

/* Phone mockup */
.hero__visual {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  padding: 40px;
}

.phone-mockup {
  width: 220px;
  background: var(--black);
  border-radius: 36px;
  padding: 12px;
  box-shadow:
    0 40px 80px rgba(0,0,0,0.25),
    0 0 0 1px rgba(255,255,255,0.08),
    inset 0 0 0 1px rgba(255,255,255,0.04);
  animation: float 5s ease-in-out infinite;
}
@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-10px); }
}

.phone-screen {
  background: #1a1a1a;
  border-radius: 26px;
  overflow: hidden;
  aspect-ratio: 9/19.5;
  display: flex;
  flex-direction: column;
}
.phone-ui { height: 100%; padding: 12px 10px; display: flex; flex-direction: column; gap: 8px; }
.phone-header { }
.phone-stories { display: flex; gap: 8px; padding: 4px 0; }
.story-bubble {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--gray-700);
  flex-shrink: 0;
}
.story-bubble.active {
  background: var(--gradient);
  box-shadow: 0 0 0 2px white, 0 0 0 3px var(--purple);
}
.phone-feed { flex: 1; display: flex; flex-direction: column; gap: 8px; overflow: hidden; }
.feed-post { border-radius: 12px; overflow: hidden; }
.feed-post__img {
  height: 90px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.8rem;
  color: rgba(255,255,255,0.6);
}
.feed-post__bar { background: #222; padding: 8px 10px; }
.feed-post__actions { display: flex; gap: 10px; color: rgba(255,255,255,0.6); font-size: 0.9rem; }

/* Float badges */
.float-badge {
  position: absolute;
  display: flex; align-items: center; gap: 8px;
  background: white;
  border-radius: var(--radius-full);
  padding: 10px 16px;
  font-size: 0.82rem;
  font-weight: 700;
  box-shadow: var(--shadow-md);
  white-space: nowrap;
  animation: float 5s ease-in-out infinite;
}
.float-badge--1 {
  top: 10%; left: 0;
  color: var(--purple);
  animation-delay: 0.5s;
}
.float-badge--1 i { color: var(--purple); font-size: 1.1rem; }
.float-badge--2 {
  bottom: 15%; right: 0;
  color: var(--orange);
  animation-delay: 1.5s;
}
.float-badge--2 i { color: var(--orange); font-size: 1.1rem; }

/* ============================================================
   FEATURES
   ============================================================ */
.features { background: var(--gray-50); }

.section-layout {
  display: flex;
  gap: 80px;
  margin-bottom: 56px;
  align-items: flex-start;
}
.section-layout .section-label { flex-shrink: 0; margin-top: 4px; }
.features__headline { font-size: clamp(1.7rem, 3vw, 2.6rem); margin-bottom: 0; }

.features-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 16px;
}

.feature-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px;
  border: 1px solid var(--gray-100);
  transition: all var(--transition);
  overflow: hidden;
  position: relative;
}
.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: transparent;
}
.feature-card--wide { grid-row: span 2; }

.feature-card__icon {
  width: 48px; height: 48px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 16px;
}
.feature-card__icon--purple { background: var(--purple-bg); color: var(--purple); }
.feature-card__icon--orange { background: var(--orange-bg); color: var(--orange); }
.feature-card__icon--blue { background: var(--blue-bg); color: var(--blue); }
.feature-card__icon--teal { background: var(--teal-bg); color: var(--teal); }

.feature-card__title {
  font-size: 1.2rem;
  font-weight: 800;
  margin-bottom: 8px;
  color: var(--black);
}
.feature-card__desc { font-size: 0.9rem; color: var(--gray-500); line-height: 1.6; }

/* Clips visual */
.feature-card__visual--clips {
  margin-top: 24px;
  background: linear-gradient(135deg, #7638FA 0%, #FF7A00 100%);
  border-radius: var(--radius-md);
  height: 140px;
  display: flex; align-items: center; justify-content: center;
  position: relative;
  overflow: hidden;
}
.clip-preview { position: relative; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; }
.clip-progress {
  position: absolute;
  bottom: 0; left: 0;
  height: 3px;
  width: 60%;
  background: rgba(255,255,255,0.8);
  border-radius: 2px;
}
.clip-play {
  font-size: 2.5rem;
  color: rgba(255,255,255,0.9);
  text-shadow: 0 2px 8px rgba(0,0,0,0.2);
}

.section-cta { margin-top: 32px; }

/* ============================================================
   SAFETY
   ============================================================ */
.safety {
  background: linear-gradient(160deg, #F0FBF7 0%, var(--white) 60%);
}
.safety__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.safety-shield {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
}
.shield-bg {
  width: 200px; height: 220px;
  background: linear-gradient(160deg, rgba(0,184,122,0.12) 0%, rgba(0,184,122,0.06) 100%);
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  position: absolute;
}
.shield-icon {
  font-size: 5rem;
  color: var(--green);
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 4px 16px rgba(0,184,122,0.3));
}
.safety-pills {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.safety-pill {
  position: absolute;
  display: flex; align-items: center; gap: 6px;
  background: white;
  border: 1px solid rgba(0,184,122,0.2);
  border-radius: var(--radius-full);
  padding: 8px 14px;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--green);
  box-shadow: var(--shadow-sm);
  white-space: nowrap;
}
.safety-pill:nth-child(1) { top: 10%; right: 5%; }
.safety-pill:nth-child(2) { top: 35%; left: 0%; }
.safety-pill:nth-child(3) { bottom: 30%; right: 0%; }
.safety-pill:nth-child(4) { bottom: 10%; left: 10%; }

/* ============================================================
   CREATORS
   ============================================================ */
.creators {
  background: linear-gradient(160deg, var(--white) 0%, #FFF9F3 100%);
}
.creators__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.creators__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-bottom: 28px;
}
.creator-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.creator-stat__num {
  font-size: 1.8rem;
  font-weight: 800;
  background: var(--gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  line-height: 1;
}
.creator-stat__label { font-size: 0.78rem; color: var(--gray-500); font-weight: 500; }

/* Creator visual */
.creators__visual { display: flex; justify-content: center; align-items: center; padding: 40px; }
.creator-cards-stack { position: relative; width: 280px; height: 280px; }

.creator-card {
  position: absolute;
  width: 220px;
  background: white;
  border-radius: var(--radius-lg);
  padding: 16px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
}
.creator-card--back { top: 0; left: 0; transform: rotate(-4deg); opacity: 0.7; }
.creator-card--front { top: 30px; right: 0; z-index: 2; transform: rotate(2deg); }
.creator-card--front:hover { transform: rotate(0deg) scale(1.02); transition: transform 0.3s; }

.creator-card__thumb {
  width: 100%; height: 100px;
  border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,0.8);
  font-size: 2rem;
  margin-bottom: 12px;
}
.creator-card__info { display: flex; flex-direction: column; gap: 2px; }
.creator-card__name { font-weight: 700; font-size: 0.9rem; }
.creator-card__followers { font-size: 0.8rem; color: var(--gray-500); }
.creator-card__badge {
  position: absolute;
  top: 10px; right: 10px;
  background: var(--orange-bg);
  color: var(--orange);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  display: flex; align-items: center; gap: 4px;
}

.earnings-badge {
  position: absolute;
  bottom: -10px; left: -10px;
  display: flex; align-items: center; gap: 10px;
  background: white;
  border-radius: var(--radius-md);
  padding: 12px 16px;
  box-shadow: var(--shadow-md);
  z-index: 3;
}
.earnings-badge > i { font-size: 1.6rem; color: var(--orange); }
.earnings-badge__num { font-weight: 800; font-size: 1.1rem; color: var(--black); line-height: 1; }
.earnings-badge__label { font-size: 0.72rem; color: var(--gray-500); margin-top: 2px; }

/* ============================================================
   TAGLINE BANNER
   ============================================================ */
.tagline-banner {
  background: var(--black);
  padding: 28px 0;
  overflow: hidden;
  position: relative;
}
.tagline-banner__inner {
  display: flex;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, black 10%, black 90%, transparent 100%);
  mask-image: linear-gradient(90deg, transparent 0%, black 10%, black 90%, transparent 100%);
}
.tagline-track {
  display: flex;
  align-items: center;
  gap: 32px;
  flex-shrink: 0;
  animation: marquee 22s linear infinite;
  white-space: nowrap;
}
.tagline-track--dup { animation-delay: -11s; }
@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-100%); }
}
.tagline-item {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--white);
  letter-spacing: -0.01em;
  flex-shrink: 0;
}
.tagline-sep { color: var(--orange); font-size: 1.1rem; flex-shrink: 0; }

/* ============================================================
   NEWS
   ============================================================ */
.news { padding: 96px 0 80px; }

.news__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 48px;
}
.news__meta .section-headline { margin-bottom: 0; }
.news__viewmore { display: flex; align-items: center; gap: 6px; font-weight: 700; color: var(--purple); padding-bottom: 4px; }
.news__viewmore:hover { gap: 10px; }
.news__viewmore-mobile { display: none; margin-top: 24px; }

.news__carousel-wrapper {
  position: relative;
  overflow: hidden;
}

.news__carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0 24px 16px;
  max-width: 1248px;
  margin: 0 auto;
  cursor: grab;
}
.news__carousel::-webkit-scrollbar { display: none; }
.news__carousel:active { cursor: grabbing; }

.news__scroll-hint {
  position: absolute;
  right: 0; top: 50%;
  transform: translateY(-50%);
  background: linear-gradient(270deg, var(--white) 60%, transparent 100%);
  width: 80px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 12px;
  pointer-events: none;
  font-size: 1.4rem;
  color: var(--gray-500);
  opacity: 0.7;
}

/* News Cards */
.news-card {
  flex: 0 0 300px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-100);
  overflow: hidden;
  scroll-snap-align: start;
  transition: all var(--transition);
  cursor: pointer;
}
.news-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: transparent;
}

.news-card__thumb {
  height: 180px;
  position: relative;
  overflow: hidden;
}
.news-card__thumb--1 { background: linear-gradient(135deg, #7638FA 0%, #A970FF 100%); }
.news-card__thumb--2 { background: linear-gradient(135deg, #FF7A00 0%, #FFD600 100%); }
.news-card__thumb--3 { background: linear-gradient(135deg, #0094FF 0%, #00C4CC 100%); }
.news-card__thumb--4 { background: linear-gradient(135deg, #00B87A 0%, #00E5A8 100%); }

.news-card__thumb-inner {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font-size: 3rem;
  color: rgba(255,255,255,0.7);
}

.news-card__body { padding: 20px; }

.news-card__tags {
  display: flex; flex-wrap: wrap; gap: 6px;
  margin-bottom: 12px;
}
.tag {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  letter-spacing: 0.03em;
}
.tag--purple { background: var(--purple-bg); color: var(--purple); }
.tag--orange { background: var(--orange-bg); color: var(--orange); }
.tag--gray { background: var(--gray-100); color: var(--gray-700); }
.tag--green { background: var(--green-bg); color: var(--green); }

.news-card__title {
  font-size: 0.95rem;
  font-weight: 700;
  line-height: 1.45;
  color: var(--black);
  margin-bottom: 12px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.news-card__date { font-size: 0.8rem; color: var(--gray-500); font-weight: 500; }

/* ============================================================
   CTA DOWNLOAD
   ============================================================ */
.cta-download {
  padding: 80px 0;
  background: var(--gray-50);
}
.cta-download__inner {
  background: var(--black);
  border-radius: var(--radius-xl);
  padding: 72px 64px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 60px;
  align-items: center;
  position: relative;
  overflow: hidden;
}
.cta-download__bg-shape {
  position: absolute;
  top: -60px; right: 200px;
  width: 400px; height: 400px;
  border-radius: 50%;
  background: var(--gradient);
  opacity: 0.15;
  filter: blur(60px);
  pointer-events: none;
}
.cta-download__content { position: relative; z-index: 1; }
.cta-download__headline {
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 800;
  color: var(--white);
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.cta-download__sub {
  font-size: clamp(1.2rem, 2.5vw, 1.8rem);
  font-weight: 400;
  color: rgba(255,255,255,0.55);
  margin-bottom: 36px;
  line-height: 1.4;
}
.cta-download__buttons { display: flex; gap: 12px; flex-wrap: wrap; }

.store-btn {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.15);
  color: white;
  border-radius: var(--radius-md);
  padding: 14px 22px;
  transition: all var(--transition);
  backdrop-filter: blur(4px);
}
.store-btn:hover {
  background: rgba(255,255,255,0.18);
  border-color: rgba(255,255,255,0.3);
  transform: translateY(-2px);
}
.store-btn__icon { font-size: 1.8rem; }
.store-btn__text { display: flex; flex-direction: column; line-height: 1.2; }
.store-btn__label { font-size: 0.7rem; opacity: 0.7; }
.store-btn__store { font-size: 1rem; font-weight: 700; }

/* Download phone visual */
.cta-download__visual { position: relative; z-index: 1; }
.download-phone {
  width: 120px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 24px;
  padding: 8px;
  box-shadow: 0 20px 40px rgba(0,0,0,0.3);
}
.download-phone__screen {
  background: rgba(255,255,255,0.05);
  border-radius: 18px;
  aspect-ratio: 9/19.5;
  display: flex;
  align-items: center;
  justify-content: center;
}
.download-phone__app {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  color: white;
}
.download-phone__logo { font-size: 2rem; }
.download-phone__name { font-size: 0.7rem; font-weight: 700; opacity: 0.8; }

/* ============================================================
   FOOTER
   ============================================================ */
.footer {
  background: var(--white);
  border-top: 1px solid var(--gray-100);
  padding: 64px 0 40px;
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 56px;
}

.footer__col-title {
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--black);
  margin-bottom: 16px;
}

.footer__links { display: flex; flex-direction: column; gap: 8px; }
.footer__links a {
  font-size: 0.88rem;
  color: var(--gray-500);
  transition: color var(--transition);
  display: inline-flex; align-items: center; gap: 4px;
}
.footer__links a:hover { color: var(--black); }
.footer__links a i { font-size: 0.75rem; opacity: 0.7; }
.footer__links--mt { margin-top: 20px; }

.footer__bottom {
  border-top: 1px solid var(--gray-100);
  padding-top: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.footer__bottom-left { display: flex; align-items: center; gap: 16px; }

.footer__logo {
  display: flex; align-items: center; gap: 8px;
  font-weight: 800; font-size: 0.95rem; color: var(--black);
}
.footer__logo i { color: var(--purple); font-size: 1.1rem; }

.footer__lang {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--gray-100);
  border: none;
  border-radius: var(--radius-full);
  padding: 6px 14px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--gray-700);
  cursor: pointer;
  transition: background var(--transition);
}
.footer__lang:hover { background: var(--gray-300); }

.footer__social { display: flex; align-items: center; gap: 8px; }
.social-icon {
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-full);
  background: var(--gray-100);
  color: var(--gray-700);
  font-size: 1rem;
  transition: all var(--transition);
}
.social-icon:hover { background: var(--black); color: var(--white); }

.footer__legal {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.footer__legal a {
  font-size: 0.8rem;
  color: var(--gray-500);
  transition: color var(--transition);
}
.footer__legal a:hover { color: var(--black); }
.footer__sep { color: var(--gray-300); font-size: 0.8rem; }

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .features-grid { grid-template-columns: 1fr 1fr; }
  .feature-card--wide { grid-row: span 1; }
}

@media (max-width: 768px) {
  :root { --header-h: 64px; }

  .header__nav { display: none; }
  .hamburger { display: flex; }

  .hero__inner { grid-template-columns: 1fr; gap: 40px; text-align: center; }
  .hero__subtext { margin-left: auto; margin-right: auto; }
  .hero__actions { justify-content: center; }
  .hero__badge { margin-left: auto; margin-right: auto; }
  .hero__visual { padding: 20px; }
  .float-badge--1 { top: 0; left: -10px; }
  .float-badge--2 { bottom: 5%; right: -10px; }

  .section { padding: 64px 0; }

  .section-layout { flex-direction: column; gap: 8px; }
  .features-grid { grid-template-columns: 1fr; }
  .feature-card--wide { grid-row: span 1; }
  .feature-card__visual--clips { height: 100px; }

  .safety__inner { grid-template-columns: 1fr; gap: 40px; }
  .safety__visual { order: -1; }
  .safety-shield { transform: scale(0.85); }

  .creators__inner { grid-template-columns: 1fr; gap: 40px; }
  .creators__visual { order: -1; }
  .creators__stats { grid-template-columns: repeat(3, 1fr); }

  .news__header { flex-direction: column; align-items: flex-start; gap: 8px; }
  .news__viewmore { display: none; }
  .news__viewmore-mobile { display: block; }
  .news-card { flex: 0 0 260px; }

  .cta-download__inner {
    grid-template-columns: 1fr;
    padding: 48px 32px;
    gap: 32px;
  }
  .cta-download__visual { display: none; }

  .footer__grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
